"""GGUF & Ollama Modelfile Exporter for Verified `.wsp` Patched Checkpoints."""

from __future__ import annotations

import json
import shutil
import subprocess
from pathlib import Path
from typing import Any, Dict, Optional


def render_ollama_modelfile(
    *,
    model_source_path: Path,
    manifest: Dict[str, Any],
    gguf_path: Optional[Path] = None,
) -> str:
    """Generates a deterministic Ollama Modelfile preserving the verified sampling protocol."""
    eval_block = manifest.get("reproducibility_and_evaluation", {})
    sampling = eval_block.get("sampling_protocol", {})
    from_target = str((gguf_path or model_source_path).resolve())

    lines = [
        f"# Generated by WSP Hub (wsphub.dev) — Verified Patch {manifest.get('patch_id', 'unknown')}",
        f"FROM {from_target}",
        f"PARAMETER temperature {sampling.get('temperature', 0.6)}",
        f"PARAMETER top_p {sampling.get('top_p', 0.95)}",
        f"PARAMETER top_k {sampling.get('top_k', 20)}",
        f"PARAMETER repeat_penalty {sampling.get('repeat_penalty', 1.0)}",
        f"PARAMETER num_predict {min(int(sampling.get('max_tokens', 8192)), 32768)}",
    ]
    for stop_seq in sampling.get("stop_sequences", []):
        escaped = json.dumps(stop_seq)
        lines.append(f"PARAMETER stop {escaped}")
    return "\n".join(lines) + "\n"


def export_gguf(
    patched_dir: Path,
    out_gguf_path: Path,
    *,
    quantization: str = "Q4_K_M",
    llama_cpp_dir: Optional[Path] = None,
) -> Dict[str, Any]:
    """Converts a WSP-patched safetensors directory into GGUF using llama.cpp when installed."""
    target_dir = patched_dir.resolve()
    if not target_dir.exists():
        raise FileNotFoundError(f"Patched directory not found: {target_dir}")

    converter = None
    if llama_cpp_dir and (llama_cpp_dir / "convert_hf_to_gguf.py").exists():
        converter = str((llama_cpp_dir / "convert_hf_to_gguf.py").resolve())
    else:
        which_conv = shutil.which("convert_hf_to_gguf.py") or shutil.which("convert-hf-to-gguf")
        if which_conv:
            converter = which_conv

    out_gguf_path.parent.mkdir(parents=True, exist_ok=True)
    if converter is None:
        recipe_path = out_gguf_path.with_suffix(".gguf.build.json")
        recipe = {
            "status": "CONVERTER_NOT_IN_PATH",
            "patched_dir": str(target_dir),
            "target_gguf": str(out_gguf_path.resolve()),
            "quantization": quantization,
            "command": f'python convert_hf_to_gguf.py "{target_dir}" --outfile "{out_gguf_path}" --outtype f16 && llama-quantize "{out_gguf_path}" "{out_gguf_path.with_stem(out_gguf_path.stem + "-" + quantization)}" {quantization}',
        }
        recipe_path.write_text(json.dumps(recipe, indent=2), encoding="utf-8")
        return recipe

    fp16_tmp = out_gguf_path.with_suffix(".f16.gguf")
    subprocess.run(
        ["python", converter, str(target_dir), "--outfile", str(fp16_tmp), "--outtype", "f16"],
        check=True,
    )
    quantizer = shutil.which("llama-quantize")
    if quantizer and quantization.upper() not in ("F16", "BF16"):
        subprocess.run([quantizer, str(fp16_tmp), str(out_gguf_path), quantization], check=True)
        fp16_tmp.unlink(missing_ok=True)
    else:
        fp16_tmp.replace(out_gguf_path)

    return {
        "status": "CONVERTED",
        "output_gguf": str(out_gguf_path.resolve()),
        "quantization": quantization,
    }


def export_ollama(
    patched_dir: Path,
    *,
    manifest: Dict[str, Any],
    ollama_tag: str,
    gguf_path: Optional[Path] = None,
    register_with_daemon: bool = False,
) -> Dict[str, Any]:
    """Writes a verified Modelfile into patched_dir and optionally registers with local Ollama."""
    modelfile_text = render_ollama_modelfile(
        model_source_path=patched_dir, manifest=manifest, gguf_path=gguf_path
    )
    modelfile_path = patched_dir.resolve() / "Modelfile"
    modelfile_path.write_text(modelfile_text, encoding="utf-8")

    registered = False
    if register_with_daemon and shutil.which("ollama"):
        subprocess.run(["ollama", "create", ollama_tag, "-f", str(modelfile_path)], check=True)
        registered = True

    return {
        "modelfile_path": str(modelfile_path),
        "ollama_tag": ollama_tag,
        "registered_with_ollama": registered,
        "run_command": f"ollama run {ollama_tag}",
    }
